     5→const CLAUDELangCompiler = require("../src/compiler.js");
     6→
     7→// 색상 정의
     8→const colors = {
     9→  reset: "\x1b[0m",
    10→  green: "\x1b[32m",
    11→  red: "\x1b[31m",
    12→  yellow: "\x1b[33m",
    13→  blue: "\x1b[34m",
