    15→
    16→class TestRunner {
    17→  constructor() {
    18→    this.passed = 0;
    19→    this.failed = 0;
    20→    this.compiler = new CLAUDELangCompiler();
    21→  }
    22→
    23→  test(name, fn) {
    24→    try {
    25→      fn();
    26→      console.log(`${colors.green}✅ PASS${colors.reset}: ${name}`);
    27→      this.passed++;
    28→    } catch (error) {
    29→      console.log(`${colors.red}❌ FAIL${colors.reset}: ${name}`);
    30→      console.log(`   ${error.message}`);
    31→      this.failed++;
    32→    }
    33→  }
    34→
    35→  assert(condition, message) {
    36→    if (!condition) {
    37→      throw new Error(message);
    38→    }
    39→  }
    40→
    41→  assertEqual(actual, expected, message) {
    42→    if (actual !== expected) {
    43→      throw new Error(
    44→        `${message} - expected '${expected}', got '${actual}'`
    45→      );
    46→    }
    47→  }
    48→
    49→  summary() {
    50→    const total = this.passed + this.failed;
    51→    console.log(`\n${colors.blue}═══════════════════════════${colors.reset}`);
    52→    console.log(`${colors.blue}테스트 결과${colors.reset}`);
    53→    console.log(`${colors.blue}═══════════════════════════${colors.reset}`);
    54→    console.log(`전체: ${total}`);
    55→    console.log(`${colors.green}성공: ${this.passed}${colors.reset}`);
    56→    console.log(`${colors.red}실패: ${this.failed}${colors.reset}`);
    57→    console.log(`${colors.blue}═══════════════════════════${colors.reset}\n`);
    58→
    59→    return this.failed === 0;
    60→  }
    61→}
