    console.log(`${colors.green}성공: ${this.passed}${colors.reset}`);
    console.log(`${colors.red}실패: ${this.failed}${colors.reset}`);
    console.log(
      `${colors.blue}${'═'.repeat(50)}${colors.reset}\n`
    );

    return this.failed === 0;
  }
}

